// Claude's review tests for A14 (import a HAR file). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { detectHar, harSummaryText, importHar } from './harImport';

function entry(method: string, url: string, opts: {
  status?: number; mime?: string; text?: string; encoding?: string; type?: string; at?: string;
  headers?: Array<{ name: string; value: string }>; postData?: string;
} = {}) {
  return {
    startedDateTime: opts.at ?? '2026-11-09T10:00:00.000Z',
    ...(opts.type ? { _resourceType: opts.type } : {}),
    request: { method, url, headers: [], ...(opts.postData ? { postData: { mimeType: 'application/json', text: opts.postData } } : {}) },
    response: {
      status: opts.status ?? 200,
      headers: opts.headers ?? [{ name: 'Content-Type', value: opts.mime ?? 'application/json' }],
      content: { mimeType: opts.mime ?? 'application/json', ...(opts.text !== undefined ? { text: opts.text } : {}), ...(opts.encoding ? { encoding: opts.encoding } : {}) },
    },
  };
}

const har = (entries: unknown[]) => ({ log: { version: '1.2', entries } });
const ids = () => {
  let n = 0;
  return () => `id${++n}`;
};
const ORIGIN = 'http://shop.test';

describe('detectHar', () => {
  it('knows a HAR by log.entries', () => {
    expect(detectHar(har([]))).toBe(true);
    expect(detectHar({ log: {} })).toBe(false);
    expect(detectHar({ mocks: [] })).toBe(false);
    expect(detectHar(null)).toBe(false);
  });
});

describe('importHar', () => {
  it('keeps fetch and XHR entries when the HAR says the type, and skips the rest', () => {
    const r = importHar(har([
      entry('GET', 'http://shop.test/api/a', { type: 'fetch', text: '{"a":1}' }),
      entry('POST', 'http://shop.test/api/b', { type: 'xhr', text: '{"b":2}' }),
      entry('GET', 'http://shop.test/app.js', { type: 'script', mime: 'text/javascript', text: 'x' }),
      entry('GET', 'http://shop.test/api/c', { type: 'image', mime: 'image/png', text: 'AA==', encoding: 'base64' }),
      entry('GET', 'http://shop.test/', { type: 'document', mime: 'text/html', text: '<html>' }),
    ]), 'session.har', ORIGIN, ids(), 5);
    expect(r.ok).toBe(true);
    if (!r.ok) return;
    const sc = r.result.project.scenarios[1]!;
    expect(sc.mocks.map((m) => `${m.method} ${m.urlPattern}`)).toEqual(['GET /api/a', 'POST /api/b']);
    expect(r.result.summary).toEqual({ mocks: 2, calls: 2, skipped: 3 });
  });

  it('without types, keeps JSON, XML and plain text, and skips HTML, CSS, scripts, images and fonts', () => {
    const r = importHar(har([
      entry('GET', 'http://shop.test/api/j', { mime: 'application/json; charset=utf-8', text: '{}' }),
      entry('GET', 'http://shop.test/api/x', { mime: 'application/xml', text: '<a/>' }),
      entry('GET', 'http://shop.test/api/p', { mime: 'application/problem+json', text: '{}' }),
      entry('GET', 'http://shop.test/api/t', { mime: 'text/plain', text: 'hi' }),
      entry('GET', 'http://shop.test/page', { mime: 'text/html', text: '<p>' }),
      entry('GET', 'http://shop.test/s.css', { mime: 'text/css', text: 'a{}' }),
      entry('GET', 'http://shop.test/s.js', { mime: 'application/javascript', text: '1' }),
      entry('GET', 'http://shop.test/i.png', { mime: 'image/png', text: 'AA==', encoding: 'base64' }),
      entry('GET', 'http://shop.test/f.woff2', { mime: 'font/woff2', text: 'AA==', encoding: 'base64' }),
    ]), 'x.har', ORIGIN, ids(), 5);
    expect(r.ok && r.result.project.scenarios[1]!.mocks.map((m) => m.urlPattern)).toEqual(['/api/j', '/api/x', '/api/p', '/api/t']);
    expect(r.ok && r.result.summary).toEqual({ mocks: 4, calls: 4, skipped: 5 });
  });

  it('one mock per method and pattern, the latest call winning', () => {
    const r = importHar(har([
      entry('GET', 'http://shop.test/api/a?x=1', { type: 'fetch', text: 'old', at: '2026-11-09T10:00:00.000Z' }),
      entry('GET', 'http://shop.test/api/a?x=2', { type: 'fetch', text: 'new', at: '2026-11-09T10:00:05.000Z' }),
      entry('POST', 'http://shop.test/api/a', { type: 'fetch', text: 'post' }),
    ]), 'x.har', ORIGIN, ids(), 5);
    if (!r.ok) throw new Error(r.error);
    const mocks = r.result.project.scenarios[1]!.mocks;
    expect(mocks.map((m) => [m.method, m.urlPattern, m.response.body])).toEqual([['GET', '/api/a', 'new'], ['POST', '/api/a', 'post']]);
    expect(r.result.summary).toEqual({ mocks: 2, calls: 3, skipped: 0 });
  });

  it("keeps another site's host, as Mock this does", () => {
    const r = importHar(har([entry('GET', 'https://api.other.test/v1/users', { type: 'fetch', text: '[]' })]), 'x.har', ORIGIN, ids(), 5);
    expect(r.ok && r.result.project.scenarios[1]!.mocks[0]!.urlPattern).toBe('https://api.other.test/v1/users');
  });

  it('copies status, body, base64 encoding, and headers without the dropped ones', () => {
    const r = importHar(har([
      entry('GET', 'http://shop.test/api/bin', {
        type: 'fetch', status: 201, mime: 'application/octet-stream', text: 'AAEC', encoding: 'base64',
        headers: [
          { name: 'Content-Type', value: 'application/octet-stream' },
          { name: 'Content-Length', value: '3' },
          { name: 'Set-Cookie', value: 'a=b' },
          { name: ':status', value: '201' },
          { name: 'X-Trace', value: 't1' },
        ],
      }),
      entry('GET', 'http://shop.test/api/empty', { type: 'fetch', status: 204 }),
    ]), 'x.har', ORIGIN, ids(), 5);
    if (!r.ok) throw new Error(r.error);
    const [bin, empty] = r.result.project.scenarios[1]!.mocks;
    expect(bin!.response).toEqual({ status: 201, headers: { 'content-type': 'application/octet-stream', 'x-trace': 't1' }, body: 'AAEC', bodyEncoding: 'base64', delayMs: 0 });
    expect(empty!.response.body).toBe('');
    expect(empty!.response.status).toBe(204);
    expect(bin!.source).toBe('recorded');
  });

  it('skips calls with no usable status', () => {
    const r = importHar(har([entry('GET', 'http://shop.test/api/a', { type: 'fetch', status: 0 })]), 'x.har', ORIGIN, ids(), 5);
    expect(r.ok && r.result.summary).toEqual({ mocks: 0, calls: 0, skipped: 1 });
  });

  it('makes a project with an empty Default and one active scenario named after the file', () => {
    const r = importHar(har([entry('GET', 'http://shop.test/api/a', { type: 'fetch', text: '1' })]), 'session.har', ORIGIN, ids(), 5);
    if (!r.ok) throw new Error(r.error);
    const p = r.result.project;
    expect(p.origins).toEqual([ORIGIN]);
    expect(p.scenarios).toHaveLength(2);
    expect(p.scenarios[0]!.mocks).toEqual([]);
    expect(p.scenarios[1]!.name).toBe('HAR session.har');
    expect(p.activeScenarioId).toBe(p.scenarios[1]!.id);
  });

  it('a HAR with no entries is an error', () => {
    const r = importHar(har([]), 'x.har', ORIGIN, ids(), 5);
    expect(r.ok).toBe(false);
  });

  it('a GraphQL POST keeps its operation name', () => {
    const r = importHar(har([
      entry('POST', 'http://shop.test/graphql', { type: 'fetch', text: '{"data":{}}', postData: '{"operationName":"GetUser","query":"query GetUser { me }"}' }),
      entry('POST', 'http://shop.test/graphql', { type: 'fetch', text: '{"data":{"x":1}}', postData: '{"operationName":"GetCart","query":"query GetCart { cart }"}' }),
    ]), 'x.har', ORIGIN, ids(), 5);
    expect(r.ok && r.result.project.scenarios[1]!.mocks.map((m) => m.graphqlOperation)).toEqual(['GetUser', 'GetCart']);
  });
});

describe('harSummaryText', () => {
  it('reads well', () => {
    expect(harSummaryText({ mocks: 3, calls: 4, skipped: 2 })).toBe('3 mocks from 4 calls (2 skipped)');
    expect(harSummaryText({ mocks: 1, calls: 1, skipped: 0 })).toBe('1 mock from 1 call');
  });
});
